        self._ptx_mod = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda and x.dtype == torch.float16
        B, C, H, W = x.shape
        out = torch.empty_like(x)

        # launch configuration: one block per channel, 256 threads per block
        grid = (C,)
        block = (256,)

        args = [
            x.data_ptr(),
            out.data_ptr(),
            self.gamma.data_ptr(),
            self.beta.data_ptr(),
            B,
            C,
            H,
            W,
            float(self.eps)
        ]

        ptx_launch(self._ptx_mod, "batchnorm_fp16", grid, block, args)
        return out
